insert into workflow_test_ids(name,value) select 'first',(result->>'requestId')::uuid from (select public.c1_workflow_create_request('c1f50000-0000-4000-8000-000000000020','c1f50000-0000-4000-8000-000000000101', ('{"partyId":"c1f50000-0000-4000-8000-000000000201","partyKind":"organization","categoryId":"c1f50000-0000-4000-8000-000000000211","amount":"70","currencyCode":"VND","basis":{"kind":"materials","lines":[{"description":"synthetic pipe","quantity":"1","unit":"item","unitPrice":"70"}],"deliverySite":"synthetic site"},"evidenceFileIds":["c1f50000-0000-4000-8000-000000000501"]}'::jsonb || jsonb_build_object('contractVersionId',(select body->>'contractVersionId' from workflow_test_ids where name='contract'))), 'c1f50000-0000-4000-8000-000000000703', 'c1f50000-0000-4000-8000-000000000704') result) q;
