select is((select v.snapshot->>'contractVersionId' from public.cost_workflow_request_versions v join public.cost_workflow_requests req on req.submitted_version_id=v.id where req.id=(select value from workflow_test_ids where name='first')),(select body->>'contractVersionId' from workflow_test_ids where name='contract'),'submission freezes original basis identity');
insert into workflow_test_ids(name,value) select 'amendment',(result->>'adjustmentId')::uuid from (select public.c1_workflow_submit_contract_adjustment('c1f50000-0000-4000-8000-000000000020','c1f50000-0000-4000-8000-000000000101', (select value from workflow_test_ids where name='contract'), '{"expectedVersion":1,"proposedCap":"140","reason":"synthetic extension","evidenceFileIds":["c1f50000-0000-4000-8000-000000000501"]}'::jsonb, 'c1f50000-0000-4000-8000-000000000725', 'c1f50000-0000-4000-8000-000000000726') result) q;
