select is((public.c1_workflow_read_contract('c1f50000-0000-4000-8000-000000000020','c1f50000-0000-4000-8000-000000000101',(select value from workflow_test_ids where name='contract'))->>'cap')::numeric,140::numeric,'approved amendment changes cap');
select lives_ok($$select public.c1_workflow_decide_request('c1f50000-0000-4000-8000-000000000020','c1f50000-0000-4000-8000-000000000101', (select value from workflow_test_ids where name='first'), jsonb_build_object('submittedVersionId',(select submitted_version_id from public.cost_workflow_requests where id=(select value from workflow_test_ids where name='first')),'decision','approve'), 'c1f50000-0000-4000-8000-000000000719', 'c1f50000-0000-4000-8000-000000000720')$$,'current manager approves same snapshot');
select is((select i.contract_version_id::text from public.cost_workflow_installments i where i.request_id=(select value from workflow_test_ids where name='first')),(select body->>'contractVersionId' from workflow_test_ids where name='contract'),'installment retains submitted historical basis despite approved current-cap amendment');
select lives_ok($$select public.c1_workflow_decide_request('c1f50000-0000-4000-8000-000000000020','c1f50000-0000-4000-8000-000000000101', (select value from workflow_test_ids where name='first'), jsonb_build_object('submittedVersionId',(select submitted_version_id from public.cost_workflow_requests where id=(select value from workflow_test_ids where name='first')),'decision','approve'), 'c1f50000-0000-4000-8000-000000000719', 'c1f50000-0000-4000-8000-000000000720')$$,'same decision replays without consuming cap twice');
